function recordLengths(text) {
        const lengths = [];
        let cur = null;
        text.split('\n').forEach(line => {
            if (line.trim().startsWith('>')) {
                if (cur !== null) lengths.push(cur);
                cur = 0;
            } else {
                cur = (cur || 0) + line.replace(/[^A-Za-z]/g, '').length;
            }
        });
        if (cur !== null) lengths.push(cur);
        return lengths.filter(n => n > 0);
    }

