function renderInto(wrap, results, q, opts) {
        opts = opts || {};
        const target = opts.target ? ` target="${opts.target}"` : '';

        if (!results.length) {
            // An exact-ID lookup finding nothing usually means the visitor typed a name or a
            // word ("BRCA1", "kinase"). Offer the search that handles those, term filled in.
            const site = sitePath;
            // Annotation Search switched off on this site (includes/toolbar.php marks the page):
            // no link into it.
            const searchOn = !document.querySelector('[data-no-search="1"]');
            // ...unless the ID Translator maps it (an ID from a source this site does not load, e.g. a
            // GenBank accession): name the gene it is, first (api/feature_search.php 'crosswalk').
            const cw = results.crosswalk || [];
            const cwHtml = cw.map(c => {
                const ext = c.external ? ' target="_blank" rel="noopener"' : target;
                return `<div class="mt-2">${moopTm('%1$s is not loaded here; it maps to %2$s',
                            `<strong>${escapeHtml(q)}</strong>`,
                            `<a href="${escapeHtml(c.url)}"${ext} class="fw-semibold font-monospace">${escapeHtml(c.id)}</a>`
                            + (c.external ? ' <i class="fa fa-external-link-alt link-icon"></i>' : ''))}
                          <span class="text-muted">(<em>${escapeHtml(c.organism.replace(/_/g, ' '))}</em>)</span>
                          · <a href="${escapeHtml(c.translator)}"${target}>${moopTh('Open in the ID Translator')}</a></div>`;
            }).join('');
            wrap.innerHTML = (cwHtml ? `<div class="small">${cwHtml}</div>` : '')
                + '<div class="small mt-2 text-muted">' + moopTh('No gene, transcript or protein has that exact ID.') + ' '
                + (q && searchOn ? `<a href="${site}/tools/search.php?q=${encodeURIComponent(q)}">${moopTh('Search annotations for “%s” →', q)}</a>` : '')
                + '</div>';
            return;
        }

        const orgDisplay = org => `<em>${org.replace(/_/g, ' ')}</em>`;

        const rowHtml = r => {
            const secondary = [orgDisplay(r.organism), r.assembly, r.gene_set]
                .filter(Boolean).join(' <span style="color:#cbd5e1">·</span> ');
            return `<tr data-search="${(r.organism + ' ' + r.type + ' ' + r.assembly + ' ' + r.gene_set).toLowerCase()}">
               <td style="line-height:1.2;">
                 <a href="${r.url}"${target}
                    class="fw-semibold font-monospace" style="font-size:0.85rem;color:var(--moop-tool-header);">${r.uniquename}</a>
                 <div class="text-muted" style="font-size:0.75rem; margin-top:1px;">${secondary}</div>
               </td>
               <td class="text-end align-top" style="padding-top:6px;">${typeChip(r.type)}</td>
             </tr>`;
        };

        const filterBar = results.length > 5
            ? `<div class="mt-2 mb-1">
                 <input type="text" class="form-control form-control-sm moop-input fs-filter"
                        placeholder="${moopTh('Filter results…')}" autocomplete="off">
               </div>`
            : '';

        wrap.innerHTML =
            `${filterBar}
             <div class="table-responsive mt-2">
               <table class="table table-sm table-hover mb-0 fs-table"
                      style="border-top:2px solid var(--moop-tool-header);">
                 <tbody>${results.map(rowHtml).join('')}</tbody>
               </table>
             </div>`;

        const filterInput = wrap.querySelector('.fs-filter');
        if (filterInput) {
            filterInput.addEventListener('input', function () {
                const term = this.value.toLowerCase();
                wrap.querySelectorAll('.fs-table tbody tr').forEach(tr => {
                    tr.style.display = tr.dataset.search.includes(term) ? '' : 'none';
                });
            });
            filterInput.focus();
        }
    }

const rowHtml = r => {
            const secondary = [orgDisplay(r.organism), r.assembly, r.gene_set]
                .filter(Boolean).join(' <span style="color:#cbd5e1">·</span> ');
            return `<tr data-search="${(r.organism + ' ' + r.type + ' ' + r.assembly + ' ' + r.gene_set).toLowerCase()}">
               <td style="line-height:1.2;">
                 <a href="${r.url}"${target}
                    class="fw-semibold font-monospace" style="font-size:0.85rem;color:var(--moop-tool-header);">${r.uniquename}</a>
                 <div class="text-muted" style="font-size:0.75rem; margin-top:1px;">${secondary}</div>
               </td>
               <td class="text-end align-top" style="padding-top:6px;">${typeChip(r.type)}</td>
             </tr>`;
        }

function lookup(q) {
        return fetch(`${sitePath}/api/feature_search.php?q=${encodeURIComponent(q)}`)
            .then(r => r.json())
            // Network failure or a non-JSON reply (a rate-limit page): one plain message,
            // not a JSON parser error.
            .catch(() => { throw new Error(moopT('Search failed. Please try again.')); })
            .then(data => {
                if (data.error) throw new Error(data.error);
                const results = data.results || [];
                results.crosswalk = data.crosswalk || [];   // only set when results is empty
                return results;
            });
    }

function search() {
        const input = document.getElementById('fs-input');
        if (!input) return;
        const q = input.value.trim();
        if (!q) { setStatus(moopT('Enter a feature ID to search.')); return; }

        const btn  = document.getElementById('fs-go');
        const wrap = document.getElementById('fs-results');

        // Restore the button's own label afterwards -- it was reset to "Go" while the
        // button reads "Search".
        const label = btn ? btn.innerHTML : '';
        if (btn)  { btn.disabled = true; btn.innerHTML = '<i class="fa fa-spinner fa-spin"></i>'; }
        if (wrap) wrap.innerHTML = '';
        setStatus(moopT('Searching…'));

        lookup(q)
            .then(results => { setStatus(''); if (wrap) renderInto(wrap, results, q, { target: '_blank' }); })
            .catch(e => setStatus(e.message, true))
            .finally(() => {
                if (btn) { btn.disabled = false; btn.innerHTML = label; }
            });
    }

function popoverFor(el) {
    if (!window.bootstrap || !bootstrap.Popover) return null;   // no Bootstrap: keep the fallback
    // The title attribute is a no-JS fallback written by field_help(), holding the help text
    // itself. Remove it BEFORE the popover is built: Bootstrap stores it as the popover's
    // heading (data-bs-original-title) and falls back to it whenever no heading is given, so an
    // (i) without a heading of its own showed its text twice — heading and body. Left in place,
    // it would also show the native browser tooltip on hover. The heading, if any, is
    // data-bs-title.
    if (!bootstrap.Popover.getInstance(el)) el.removeAttribute('title');
    return bootstrap.Popover.getOrCreateInstance(el, {
      trigger: 'manual',
      title: el.getAttribute('data-bs-title') || ''
    });
  }

function closeOpen() {
    if (!openEl) return;
    var pop = bootstrap.Popover.getInstance(openEl);
    if (pop) pop.hide();
    openEl = null;
  }

function initFieldHelp(root) {
    (root || document).querySelectorAll(SELECTOR).forEach(popoverFor);
  }

