function poll() {
        $.ajax({ url: api, method: 'POST', data: { status: 1 }, dataType: 'json' }).done(function (res) {
            const p     = res && res.progress;
            const fresh = p && since !== null && p.started_at >= since - 5;
            if (res && res.running) {
                if (fresh && !p.finished) {
                    busy('Rebuilding ' + p.index + ' of ' + p.total + '…');
                    render('<div><span class="spinner-border spinner-border-sm text-secondary me-1"></span> '
                         + 'Rebuilding <strong>' + p.index + ' of ' + p.total + '</strong>: ' + label(p.current)
                         + ' <span class="text-muted">(started ' + clock(p.started_at) + ')</span></div>' + listOf(p));
                } else {
                    busy('Starting…');
                    render('<span class="spinner-border spinner-border-sm text-secondary me-1"></span> '
                         + 'Housekeeping is running in the background; the gene-track rebuild starts when it reaches it. '
                         + 'This page updates by itself.');
                }
                setTimeout(poll, POLL_MS);
                return;
            }
            // Not running any more: report what this run did, then reload so the card is current.
            if (fresh && p.finished) {
                const bad = (p.failed || []).length;
                render('<div class="' + (bad ? 'text-warning' : 'text-success') + ' fw-semibold">'
                     + (p.total === 0 ? 'Nothing needed rebuilding.'
                        : 'Rebuilt ' + (p.done || []).length + ' of ' + p.total + (bad ? ', ' + bad + ' failed' : '')
                          + (p.left ? ', ' + p.left + ' left for the next run' : '') + ' in ' + p.seconds + ' s.')
                     + '</div>' + listOf(p) + '<div class="text-muted mt-1">Refreshing the card…</div>');
            } else {
                render('Housekeeping finished. Refreshing the card…');
            }
            btn.innerHTML = original;
            setTimeout(() => window.location.reload(), 2500);
        }).fail(function (xhr) {
            btn.disabled = false;
            btn.innerHTML = original;
            render('⚠ Lost touch with the server (HTTP ' + xhr.status + '). The rebuild may still be running — reload in a minute.', 'text-danger');
        });
    }

function x(pos) {
            var f = (pos - gStart) / span;
            return (flip ? 1 - f : f) * W;
        }

function rect(a, b, y, h, fill) {
            var x1 = x(a), x2 = x(b);
            var left = Math.min(x1, x2);
            var w = Math.max(Math.abs(x2 - x1), 0.8);   // never vanish entirely
            return '<rect x="' + left.toFixed(1) + '" y="' + y + '" width="' + w.toFixed(1) +
                   '" height="' + h + '" fill="' + fill + '" rx="0.5"/>';
        }

function build(iso) {
            var hasCds   = iso.cds && iso.cds.length > 0;
            var exonFill = hasCds ? COLOR_EXON : COLOR_NOCDS;

            var parts = [];
            // Backbone spans only this isoform, so a short transcript reads as short.
            parts.push(rect(iso.start, iso.end, H / 2 - 0.75, 1.5, COLOR_BACKBONE));
            (iso.exons || []).forEach(function (e) {
                parts.push(rect(e.start, e.end, 4, H - 8, exonFill));
            });
            // CDS drawn over the exons and taller, exactly as the main diagram does.
            (iso.cds || []).forEach(function (c) {
                parts.push(rect(c.start, c.end, 2, H - 4, COLOR_CDS));
            });

            var svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
            svg.setAttribute("class", "iso-minimap");
            svg.setAttribute("width", W);
            svg.setAttribute("height", H);
            svg.setAttribute("viewBox", "0 0 " + W + " " + H);
            svg.setAttribute("aria-hidden", "true");     // decorative; the name carries the meaning
            svg.setAttribute("focusable", "false");
            svg.style.pointerEvents = "none";            // never intercept the collapse toggle
            svg.innerHTML = parts.join("");
            return svg;
        }

function buildIframeUrl(organism, assembly, loc) {
        const configUrl = `${site}/api/jbrowse2/config.php`
            + `?organism=${encodeURIComponent(organism)}`
            + `&assembly=${encodeURIComponent(assembly)}`;

        const assemblyName = `${organism}_${assembly}`;
        const meta = (typeof jbAssemblyMeta !== 'undefined' && jbAssemblyMeta[assemblyName])
                      ? jbAssemblyMeta[assemblyName] : {};

        // Prefer explicit loc, fall back to first scaffold from .fai
        const effectiveLoc = loc || meta.firstLoc || '';

        // Prefer deep-link gene tracks (already set by PHP), fall back to meta
        const geneTracks = [
            ...(Array.isArray(jbGeneTracks) && jbGeneTracks.length
                ? jbGeneTracks
                : (meta.geneTracks || [])),
            // May be a comma-separated list: a linkout can add several session
            // tracks that all need opening, not just the first.
            ...(jbSessionTrackId ? String(jbSessionTrackId).split(',').filter(Boolean) : []),
        ];

        let url = `${site}/jbrowse2/index.html?config=${encodeURIComponent(configUrl)}`
                + `&assembly=${encodeURIComponent(assemblyName)}`
                + `&tracklist=true`;

        if (effectiveLoc) url += `&loc=${encodeURIComponent(effectiveLoc)}`;
        if (geneTracks.length) url += `&tracks=${encodeURIComponent(geneTracks.join(','))}`;
        if (jbSessionTracks)   url += `&sessionTracks=${encodeURIComponent(jbSessionTracks)}`;

        return url;
    }

function resizeViewer() {
        const wrap = document.getElementById('jb-iframe-wrap');
        if (!wrap || wrap.closest('#jb-viewer')?.style.display === 'none') return;
        // The whole window less the viewer's own toolbar row: launch() scrolls the viewer to the top, so
        // the site banner (300px on simrbase) and the navbar scroll away instead of eating the height.
        // Visitors said it was too small (2026-11-25): it used to fill only what was left below them.
        // Never under 500px, so tracks stay readable on a short screen.
        const bar = wrap.previousElementSibling;
        const barH = bar ? bar.getBoundingClientRect().height + 8 : 0;
        wrap.style.height = Math.max(500, window.innerHeight - barH - 8) + 'px';
    }

