        const base = String(label || 'menu').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 40) || 'menu';
        let key = base, n = 2;
        while (menu.some(m => m.type === 'dropdown' && m.key === key)) key = base + '-' + (n++);
        return key;
    }

