function getAnnModel() {
        if (annModel) return annModel;
        annModel = [];
        const sel = document.querySelector('.mm-ann-src-select');
        sel?.querySelectorAll('optgroup').forEach(og => annModel.push({
            type: og.dataset.type || og.label,
