}

function togglePath(button, organism_path) {
    // The path box sits right after the button (found from it, not by an id built from the
    // organism name, which two names could share). textContent: the path is shown, not parsed.
    let pathDiv = button.nextElementSibling;
    if (pathDiv && pathDiv.classList.contains('org-path')) {
        const hidden = pathDiv.style.display === 'none';
        pathDiv.style.display = hidden ? 'block' : 'none';
        button.innerHTML = hidden ? '<i class="fa fa-folder-open"></i> Hide Path' : '<i class="fa fa-folder"></i> View Path';
        return;
    }
    pathDiv = document.createElement('div');
    pathDiv.className = 'mt-2 org-path';
    const small = document.createElement('small');
    small.className = 'font-monospace text-muted';
    small.style.cssText = 'user-select: all; cursor: text;';
    small.textContent = organism_path;
    pathDiv.appendChild(small);
    button.after(pathDiv);
    button.innerHTML = '<i class="fa fa-folder-open"></i> Hide Path';
}

function attachImageUploadHandler(imageItemElement, organism) {
  const uploadBtn = imageItemElement.querySelector('.upload-image-btn');
  const fileInput = imageItemElement.querySelector('.image-upload-input');
  const fileNameInput = imageItemElement.querySelector('.image-file');

  uploadBtn.addEventListener('click', function() {
    fileInput.click();
  });

  fileInput.addEventListener('change', function(e) {
    if (this.files.length > 0) {
      const file = this.files[0];
      const formData = new FormData();
      formData.append('upload_image', true);
      formData.append('image_file', file);

      // Show loading state
      uploadBtn.disabled = true;
      uploadBtn.textContent = 'Uploading...';

      fetch('manage_organisms.php', {
        method: 'POST',
        body: formData
      })
      .then(response => response.json())
      .then(data => {
        uploadBtn.disabled = false;
        uploadBtn.textContent = 'Upload';

        if (data.success) {
          fileNameInput.value = data.filename;
          alert('Image uploaded successfully!');
        } else {
          alert('Upload failed: ' + (data.error || 'Unknown error'));
        }
      })
      .catch(error => {
        uploadBtn.disabled = false;
        uploadBtn.textContent = 'Upload';
        alert('Upload error: ' + error.message);
      });
    }
  });
}

async function openOrganismModal(type, organism, assembly, geneSet) {
    const modalEl = document.getElementById('dynamicModal');
    if (!modalEl) return;

    // Show loading state immediately
    modalEl.innerHTML = `
        <div class="modal-dialog modal-lg">
            <div class="modal-content">
                <div class="modal-body text-center py-5">
                    <div class="spinner-border text-primary" role="status">
                        <span class="visually-hidden">Loading...</span>
                    </div>
                    <p class="mt-3 mb-0 text-muted">Loading...</p>
                </div>
            </div>
        </div>`;

    let bsModal = bootstrap.Modal.getInstance(modalEl) || new bootstrap.Modal(modalEl);
    bsModal.show();

    try {
        const csrf = document.querySelector('meta[name="csrf-token"]')?.content || '';
        const resp = await fetch(`${sitePath}/admin/api/get_organism_modal.php`, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/x-www-form-urlencoded',
                'X-CSRF-Token': csrf
            },
            body: new URLSearchParams({ type, organism, assembly: assembly || '' })
        });

        if (!resp.ok) throw new Error(`Server error ${resp.status}`);
        modalEl.innerHTML = await resp.text();

        // Enable click-to-open info popovers on section headers (the (i) icons that
        // replaced the old "Required:" boxes). Bootstrap's data-api does not auto-init
        // popovers, so wire them up explicitly after injecting the modal HTML.
        // Section (i) icons are the shared field_help() buttons: let field-help.js set them
        // up (it also drops the no-JS title fallback, so no tooltip doubles the popover),
        // then any other popover in the modal; never two instances on one element.
        if (window.MoopFieldHelp) window.MoopFieldHelp.init(modalEl);
        modalEl.querySelectorAll('[data-bs-toggle="popover"]').forEach(el => {
          if (!bootstrap.Popover.getInstance(el)) new bootstrap.Popover(el);
        });

        // Re-apply Bootstrap modal behaviour after innerHTML replacement
        bsModal = bootstrap.Modal.getInstance(modalEl) || new bootstrap.Modal(modalEl);

        // Opened from a gene-set line: bring that gene set's card into view and mark it,
        // so the click lands on what was clicked rather than the top of the assembly.
        if (geneSet) {
            const card = Array.from(modalEl.querySelectorAll('[data-gene-set]'))
                .find(el => el.dataset.geneSet === geneSet);
            if (card) {
                // After the fade-in: while the modal is still transitioning it is not yet
                // scrollable, and scrollIntoView silently does nothing.
                const focus = () => {
                    card.scrollIntoView({ block: 'center' });
                    card.classList.add('gs-focus');
                    setTimeout(() => card.classList.remove('gs-focus'), 2500);
                };
                setTimeout(focus, 350);  // Bootstrap's fade is 300 ms
            }
        }

        // Wire up image upload handlers for the metadata modal
        if (type === 'metadata') {
            const container = document.getElementById('images-container-' + organism);
            if (container) {
                container.querySelectorAll('.image-item').forEach(item => {
                    attachImageUploadHandler(item, organism);
                });
            }
        }
    } catch (err) {
        modalEl.innerHTML = `
