function submitQuickAddGroup() {
  const groupName = document.getElementById('quickAddGroupName').value.trim();
  const resultDiv = document.getElementById('quickAddResult');
  const btn       = document.getElementById('quickAddSubmitBtn');

  if (!groupName) {
    resultDiv.innerHTML = '<div class="alert alert-warning py-1 px-2 small mb-0">Enter a group name.</div>';
    resultDiv.style.display = '';
    return;
  }

  btn.disabled = true;
  btn.innerHTML = '<i class="fa fa-spinner fa-spin"></i> Adding…';

  const tok = document.querySelector('meta[name="csrf-token"]')?.content || '';

  fetch(sitePath + '/admin/api/quick_add_group.php', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/x-www-form-urlencoded',
      'X-CSRF-Token': tok
    },
    body: 'organism=' + encodeURIComponent(_quickAddOrganism) +
          '&group_name=' + encodeURIComponent(groupName)
  })
  .then(r => r.json())
  .then(data => {
    btn.disabled = false;
    btn.innerHTML = '<i class="fa fa-plus"></i> Add Group';
    if (data.success) {
      resultDiv.innerHTML =
        '<div class="alert alert-success py-1 px-2 small mb-0"><i class="fa fa-check"></i> ' +
        'Added ' + data.added + ' entr' + (data.added === 1 ? 'y' : 'ies') +
        ' to <strong>' + escapeHtml(data.group) + '</strong>.</div>';
      resultDiv.style.display = '';
      _updateGroupsCell(_quickAddCellId, _quickAddOrganism, data.group);
      setTimeout(() => {
        bootstrap.Modal.getInstance(document.getElementById('quickAddGroupModal'))?.hide();
      }, 1400);
    } else {
      resultDiv.innerHTML =
        '<div class="alert alert-danger py-1 px-2 small mb-0"><i class="fa fa-times"></i> ' +
        escapeHtml(data.error || 'Unknown error') + '</div>';
      resultDiv.style.display = '';
    }
  })
  .catch(err => {
    btn.disabled = false;
    btn.innerHTML = '<i class="fa fa-plus"></i> Add Group';
    resultDiv.innerHTML =
      '<div class="alert alert-danger py-1 px-2 small mb-0">Request failed: ' + escapeHtml(String(err)) + '</div>';
    resultDiv.style.display = '';
  });
}

function _updateGroupsCell(cellId, organism, groupName) {
  const cell = document.getElementById(cellId);
  if (cell) {
    cell.innerHTML =
      '<span class="btn btn-sm btn-outline-success disabled"><i class="fa fa-check-circle"></i> OK</span>' +
      '<div class="mt-1"><span class="badge bg-secondary">' + escapeHtml(groupName) + '</span></div>';
  }
  // Remove 'groups' from data-issues on the row so the filter updates
  const table = document.getElementById('organismsTable');
  if (!table) return;
  table.querySelectorAll('tbody tr').forEach(row => {
    const issues = (row.dataset.issues || '').split(' ').filter(i => i !== 'groups');
    // Match on organism name in data or by scanning the first cell link
    const link = row.querySelector('td:first-child a');
    if (link && link.textContent.trim().startsWith(organism)) {
      row.dataset.issues = issues.join(' ');
      const noIssues = issues.every(i => i === '');
      if (noIssues) row.dataset.status = 'complete';
    }
  });
}

function typeLabel(section) {
      var b = section.querySelector("h5 .badge");
      if (!b) return section.id || "Annotations";
      var c = b.cloneNode(true);
      var pill = c.querySelector(".annot-count-badge");
      if (pill) pill.remove();
      return c.textContent.trim();
    }

function splitChild(text) {
      var m = /^(.*?)\s*\(([^)]+)\)\s*$/.exec(text.trim());
      return m ? { label: m[1], tag: m[2] } : { label: text.trim(), tag: "" };
    }

function countFor(el) {
      if (!el) return "";
      var v = el.getAttribute("data-nav-count");
      if (v === null) v = el.getAttribute("data-annot-count");
      if (v === null) v = el.getAttribute("data-annot-total");
      if (v === null) return "";
      var n = parseInt(v, 10);
      return isNaN(n) || n <= 0 ? "" : String(n);
    }

function mk(el, label, lvl, tag) {
      var node = { key: "pn" + kc++, el: el, label: label, lvl: lvl, tag: tag || "",
                   count: countFor(el), children: [], parent: null };
      var words = el ? el.getAttribute("data-nav-count-words") : null;
      node.countWords = words !== null ? words : (node.count ? moopT('%s annotations', node.count) : "");
      reg[node.key] = node;
      return node;
    }

function directSections(scope, ownerCard) {
      var out = [];
      scope.querySelectorAll(".annotation-section").forEach(function (sec) {
        if (sec.closest(".annotation-card") === ownerCard) out.push(sec);
      });
      return out;
    }

function directCards(scope, ownerCard) {
      var out = [];
      scope.querySelectorAll(".annotation-card").forEach(function (card) {
        var above = card.parentElement ? card.parentElement.closest(".annotation-card") : null;
        if (above === ownerCard) out.push(card);
      });
      return out;
    }

function buildCard(card, lvl) {
      var badge = card.querySelector(".child-feature-badge");
      var sc = splitChild(badge ? badge.textContent : "Feature");
      var node = mk(card, sc.label, lvl, sc.tag);
      directSections(card, card).forEach(function (sec) {
        var leaf = mk(sec, typeLabel(sec), lvl + 1);
        leaf.parent = node; node.children.push(leaf);
      });
      directCards(card, card).forEach(function (sub) {
        var child = buildCard(sub, lvl + 1);
        child.parent = node; node.children.push(child);
      });
      return node;
    }

function renderList(list) {
      return '<ul class="pnav-list">' + list.map(function (n) {
