          opened.push(c);
          window.bootstrap.Collapse.getOrCreateInstance(c).show();
        } else {
          c.classList.add("show");
        }
      }

function afterShown(list, fn) {
      var pending = list.filter(function (c) { return !c.classList.contains("show") || c.classList.contains("collapsing"); });
      if (!pending.length) { fn(); return; }
      var done = false, left = pending.length;
      function finish() { if (!done) { done = true; fn(); } }
      pending.forEach(function (c) {
        c.addEventListener("shown.bs.collapse", function h() {
          c.removeEventListener("shown.bs.collapse", h);
          if (--left === 0) finish();
        });
      });
      setTimeout(finish, 1000);
    }

function h() {
          c.removeEventListener("shown.bs.collapse", h);
          if (--left === 0) finish();
        }

function scrollBehaviorFor(targetTop) {
      if (reduce) return "instant";
      var distance = Math.abs(targetTop - window.scrollY);
      return distance > SMOOTH_MAX_PX * window.innerHeight ? "instant" : "smooth";
    }

function coveredTop() {
      var bottom = 0;
      document.querySelectorAll("nav.navbar, .pnav-jumpbar").forEach(function (el) {
        var cs = getComputedStyle(el);
        if ((cs.position === "sticky" || cs.position === "fixed") && el.getClientRects().length) {
          // where it pins (its CSS top) + its height = how far down the window it covers
          bottom = Math.max(bottom, (parseFloat(cs.top) || 0) + el.getBoundingClientRect().height);
        }
      });
      return bottom ? bottom + 8 : 0;
    }

function goTo(key) {
      var node = reg[key];
      if (!node) return;
      // Measure only once the sections it opened have finished opening (see expandAncestors)
      afterShown(expandAncestors(node.el), function () {
        var top = node.el.getBoundingClientRect().top + window.scrollY - coveredTop();
        if (top <= TOP_SNAP_PX) top = 0;
        window.scrollTo({ top: top, behavior: scrollBehaviorFor(top) });
      });
    }

function wireLinks(root, isDropdown) {
      root.querySelectorAll(".pnav-link").forEach(function (a) {
