                '<em>' + escapeHtml(cb.dataset.label) + '</em> › ' + escapeHtml(cb.dataset.asmDisplay || cb.dataset.asm)
                + ' › ' + escapeHtml(cb.dataset.gsDisplay || cb.dataset.gs));
            return;
        }
        renderPanel(on);
        renderSummary(all, on);

        const allOn = all.length > 0 && on.length === all.length;
        const toggleLabel = document.querySelector('.scope-toggle-all-label');
        if (toggleLabel) toggleLabel.textContent = allOn ? moopT('Deselect all') : moopT('Select all');
        const toggleIcon = document.querySelector('.scope-toggle-all-icon');
        if (toggleIcon) toggleIcon.className = 'fas me-1 scope-toggle-all-icon ' + (allOn ? 'fa-times' : 'fa-check-double');

        if (!countsEl) return;
        if (!on.length) {
            countsEl.textContent = moopT('Select at least one organism above');
            return;
        }
        // Organisms / assemblies / gene sets in full: one click on a collapsed row can take
        // four gene sets with it, and this is where that shows. Each count is its own phrase
        // (singular and plural as two literals, CLAUDE.md §7b) placed into one sentence.
        const orgs = new Set(on.map((c) => c.dataset.org)).size;
        const asms = new Set(on.map((c) => c.dataset.org + '|' + c.dataset.asm)).size;
        const gs   = on.length;
        countsEl.textContent = moopT('%s, %s, %s selected',
            orgs === 1 ? moopT('%d organism', orgs) : moopT('%d organisms', orgs),
            asms === 1 ? moopT('%d assembly', asms) : moopT('%d assemblies', asms),
            gs   === 1 ? moopT('%d gene set', gs)   : moopT('%d gene sets', gs));
    }

function renderSummary(all, on) {
        const el = document.getElementById('scope-summary');
        if (!el) return;
        if (el.dataset.unit === 'gene_set') {   // one organism: count its gene sets
            el.textContent = !on.length ? moopT('Nothing selected — pick at least one gene set')
                : on.length === all.length ? moopT('Searching all %d gene sets', all.length)
                : moopT('Searching %d of %d gene sets', on.length, all.length);
            return;
        }
        const total = new Set(all.map((c) => c.dataset.org)).size;
        const n     = new Set(on.map((c) => c.dataset.org)).size;
        el.textContent = !n ? moopT('Nothing selected — pick at least one organism')
            : (n === total && on.length === all.length) ? moopT('Searching all %d organisms', total)
            : moopT('Searching %d of %d organisms', n, total);
    }

function renderPanel(on) {
        if (!panelEl) return;
        // Grouped by organism, in list order, so the panel reads like the list beside it.
        // An organism with several gene sets lists ALL of them, each with a checkbox, so one can
        // be dropped or added back here without the Details switch (Sofia, 2026-11-20). One with
        // a single gene set keeps a plain line: a checkbox there would only repeat the ×.
        const byOrg = {};
        on.forEach((cb) => {
            const org = cb.dataset.org;
            byOrg[org] ??= { label: cb.dataset.label || String(org).replace(/_/g, ' '), cn: cb.dataset.cn || '',
                             all: boxes().filter((c) => c.dataset.org === org) };
        });
        const orgs = Object.keys(byOrg);
        if (countEl) countEl.textContent = orgs.length;

        if (!orgs.length) {
            // Says what to DO -- never "none = all organisms" (see the partial).
            panelEl.innerHTML =
                '<div class="text-muted small p-2 fst-italic">' + moopTh('None yet — pick at least one organism') + '</div>';
            return;
        }
        panelEl.innerHTML = orgs.map((org) => {
            const d = byOrg[org];
            // .sci-name, not <em>: organism names follow the site-wide italic rule.
            return `<div class="px-2 py-1 border-bottom">
                <div class="d-flex justify-content-between align-items-start">
                  <span><strong class="sci-name">${escapeHtml(d.label)}</strong>${
                      d.cn ? ' <span class="text-muted small">· ' + escapeHtml(d.cn) + '</span>' : ''
                  }</span>
                  <button type="button" class="btn btn-link btn-sm p-0 ms-2 text-danger flex-shrink-0 scope-panel-remove"
                          data-org="${escapeHtml(org)}" title="${moopTh('Remove')}"
                          aria-label="${moopTh('Remove %s from selection', d.label)}"><i class="fas fa-times"></i></button>
                </div>
                ${d.all.length === 1
                    ? `<div class="text-muted ps-2" style="font-size:0.75rem;">› ${escapeHtml(gsText(d.all[0]))}</div>`
                    : d.all.map((c) => `<label class="d-flex align-items-start gap-1 ps-2 mb-0 ${c.checked ? '' : 'text-muted'}" style="font-size:0.75rem; cursor:pointer;">
                        <input type="checkbox" class="form-check-input mt-0 flex-shrink-0 scope-panel-gs"
                               data-org="${escapeHtml(org)}" data-asm="${escapeHtml(c.dataset.asm)}" data-gs="${escapeHtml(c.dataset.gs)}"${c.checked ? ' checked' : ''}>
                        <span>${escapeHtml(gsText(c))}</span></label>`).join('')}
              </div>`;
        }).join('');
    }

function runFilter() {
        const q = (filterEl ? filterEl.value : '').trim().toLowerCase();
        const simpleView = !detailOn();
        list.querySelectorAll('.scope-row').forEach((row) => {
            const show = (display, forced, hl) => {
                row.style.display = display;
                row.classList.toggle('scope-detail-forced', forced);
                // Cleared on every non-matching branch too: a stale <mark> from the previous
                // keystroke would highlight text the current query never matched.
                highlightScopeDetail(row, hl);
            };
            // '' hands display back to the stylesheet, which keeps the secondary rows hidden
            // in simple view -- 'flex' here would undo the collapse.
            if (!q) return show('', false, '');
            const all    = row.dataset.search || '';
            const simple = row.dataset.searchSimple || all;
            const detail = row.dataset.searchDetail || '';
            if (!all.includes(q)) return show('none', false, '');
            const detailMatch = detail.includes(q);
            const detailOnly  = detailMatch && !simple.includes(q);
            // Simple view: a SECONDARY row shows only when the query hit its own assembly or gene
            // set; filtering by organism name must not re-expose the rows the collapse hid.
            if (simpleView && row.classList.contains('scope-row-secondary') && !detailOnly) {
                return show('none', false, '');
            }
            show('flex', simpleView && detailOnly, detailMatch ? q : '');
        });
    }

const show = (display, forced, hl) => {
                row.style.display = display;
                row.classList.toggle('scope-detail-forced', forced);
                // Cleared on every non-matching branch too: a stale <mark> from the previous
                // keystroke would highlight text the current query never matched.
                highlightScopeDetail(row, hl);
            }

function showAll() {
        list.classList.remove('scope-limited');
        document.getElementById('scope-only-note')?.remove();
        if (filterEl && filterEl.value) { filterEl.value = ''; runFilter(); }
        if (single) scrollToRow(list.querySelector('.scope-row.selected'));
    }

function organisms() {
        return [...new Set(checked().map((c) => c.dataset.org))];
    }

function scope() {
        const on = organisms();
        const out = {};
        let excluded = false;
        boxes().forEach((cb) => {
            if (!on.includes(cb.dataset.org)) return;
            ((out[cb.dataset.org] ??= {})[cb.dataset.asm] ??= {})[cb.dataset.gs] = cb.checked;
            if (!cb.checked) excluded = true;
        });
        return excluded ? out : null;
    }

function highlightScopeDetail(row, query) {
    const detail = row ? row.querySelector('.scope-row-detail') : null;
    if (!detail) return;

    if (detail._moopOrigHtml === undefined) {
        if (!query) return;   // never highlighted: nothing to restore
        detail._moopOrigHtml = detail.innerHTML;
    }
    const orig = detail._moopOrigHtml;
    if (!query) { detail.innerHTML = orig; return; }

    const pattern = escapeRegExp(query);
    detail.innerHTML = orig.replace(/([^<>]+)/g, (text) =>
        text.replace(new RegExp(pattern, 'gi'), (m) => `<mark class="scope-hl">${m}</mark>`)
    );
}

function moopSearchTerms(input) {
    const trimmed = String(input || '').trim();
    if (trimmed === '') return [];

    // "zinc finger" is a single phrase query; its length is the phrase's length.
    if (/^".*"$/.test(trimmed)) {
        const phrase = trimmed.slice(1, -1).trim();
        return phrase === '' ? [] : [phrase];
    }

    return trimmed.split(/\s+/).filter(t => /[\p{L}\p{N}]/u.test(t));
}

function moopSearchInputIsUsable(input) {
    return moopSearchTerms(input).some(t => t.length >= MOOP_MIN_TERM_LENGTH);
}

function moopSearchInputHint() {
    return 'Enter at least ' + MOOP_MIN_TERM_LENGTH + ' characters in one word — '
         + 'single letters match too much to be useful. Short words are fine '
         + 'alongside longer ones, e.g. "histone deacetylase 1".';
}

function moopHighlightableTerms(input) {
    return moopSearchTerms(input).filter(t => t.length >= MOOP_MIN_TERM_LENGTH);
}

function moopTermHighlight(text, term, exactFoundInRow) {
    if (!text || !term) return null;
    const hay = String(text);
    const lower = hay.toLowerCase();

    // The literal term the user typed, wherever it appears.
    if (lower.indexOf(term.toLowerCase()) !== -1) {
        return { text: term, exact: true };
    }

    // The exact term was found SOMEWHERE ELSE in this row, so this row is explained and a
    // shortened guess here adds nothing but noise. Searching HDAC used to mark `HD` inside
    // "PHD finger protein 12" in the Description column while the Annotation Description
    // legitimately matched `HDAC` -- and because Description comes first, the wrong,
    // shorter mark is the one the user sees first.
    if (exactFoundInRow) return null;

    for (let n = term.length - 1; n >= MOOP_MIN_TERM_LENGTH; n--) {
        const probe = term.slice(0, n);
        const at = lower.indexOf(probe.toLowerCase());
        if (at === -1) continue;
        // A shortened probe must land at a WORD START. Porter only strips suffixes, so a
        // stem and its inflection share a prefix FROM THE BEGINNING OF THE WORD: `protein`
        // opens `proteins`. A mid-word hit is never that relationship -- `HD` inside `PHD`
        // is a coincidence of letters, not a stem. Without this test the trimming loop will
        // eventually find almost any short prefix somewhere in a long description.
        if (at > 0 && /[A-Za-z0-9]/.test(hay[at - 1])) {
            // Try later positions of the same probe before giving up on this length.
            let next = lower.indexOf(probe.toLowerCase(), at + 1);
            let ok = false;
            while (next !== -1) {
                if (!/[A-Za-z0-9]/.test(hay[next - 1])) { ok = true; break; }
                next = lower.indexOf(probe.toLowerCase(), next + 1);
            }
            if (!ok) continue;
        }
        return { text: probe, exact: false };
    }
    return null;
}

function tmeta(t) {
        return TMETA[t] || { label: t, hl: '#f0f0f0', swatch: '#999' };
    }

function blendHex(colors) {
        if (!colors.length) return null;
        const [r, g, b] = colors
            .map(c => { const n = parseInt(c.slice(1), 16); return [(n >> 16) & 0xff, (n >> 8) & 0xff, n & 0xff]; })
            .reduce(([ar, ag, ab], [cr, cg, cb]) => [ar + cr, ag + cg, ab + cb], [0, 0, 0])
            .map(v => v / colors.length);
        return '#' + [r, g, b].map(v => Math.round(v).toString(16).padStart(2, '0')).join('');
    }

function fetchSeq(seqname, start, end, strand) {
        const key = `${seqname}:${start}:${end}:${strand}`;
        if (_seqCache.has(key)) return Promise.resolve(_seqCache.get(key));
        const site   = (typeof moopSite !== 'undefined') ? moopSite : window.sitePath;
        const params = new URLSearchParams({ organism: moopOrganism, assembly: moopAssembly, seqname, start, end, strand });
        return fetch(`${site}/api/get_sequence.php?${params}`)
            .then(r => r.json())
            .then(data => { if (data.error) throw new Error(data.error); _seqCache.set(key, data); return data; });
    }

function buildIntervals(isoform) {
        const flip = isoform.strand === '-';
        const base = flip ? isoform.end : isoform.start;
        const out  = [];

        const push = (gStart, gEnd, type) => {
            const s = flip ? (base - gEnd)   : (gStart - base);
            const e = flip ? (base - gStart) : (gEnd   - base);
            out.push({ s, e, type });
        };

        const cdsList = (isoform.cds || []).slice().sort((a, b) => a.start - b.start);
        const hasCds  = cdsList.length > 0;

        for (const c of cdsList) push(c.start, c.end, 'CDS');

        // On a CODING transcript, the part of an exon that is not CDS is UTR. Not
        // "implied UTR" — UTR. The hedge existed because many GFFs give only exon+CDS
        // records and leave the UTR to be worked out, but that is a fact about the file
        // we read, not about the biology, and the reader does not have it and cannot use
        // it. So the exon is SPLIT here and each piece labelled for what it is, which
        // also gives every base exactly one identity: a segment carrying both `exon` and
        // `five_prime_utr` would blend two highlight colours into a muddy third.
        //
        // A NON-coding transcript keeps plain `exon`, which is equally correct — with no
        // CDS there is nothing for a region to be untranslated relative to.
        const codingStart = hasCds ? Math.min(...cdsList.map(c => c.start)) : 0;
        const codingEnd   = hasCds ? Math.max(...cdsList.map(c => c.end))   : 0;

        // Genomic "before the CDS" is 5' on the plus strand and 3' on the minus strand.
        const utrBefore = flip ? 'three_prime_utr' : 'five_prime_utr';
        const utrAfter  = flip ? 'five_prime_utr'  : 'three_prime_utr';

        for (const x of (isoform.exons || [])) {
            const type = (x.type || 'exon').toLowerCase();

            // Already-declared UTR records pass straight through, and so does every exon
            // on a non-coding transcript.
            if (type !== 'exon' || !hasCds) { push(x.start, x.end, type); continue; }

            // Subtract the CDS blocks from this exon; whatever remains is untranslated.
            let cursor = x.start;
            for (const c of cdsList) {
                if (c.end < cursor || c.start > x.end) continue;      // no overlap
                if (c.start > cursor) {
                    push(cursor, c.start - 1, c.start - 1 < codingStart ? utrBefore : utrAfter);
                }
                cursor = Math.max(cursor, c.end + 1);
            }
            if (cursor <= x.end) {
                push(cursor, x.end, cursor > codingEnd ? utrAfter : utrBefore);
            }
        }

        // Derive introns: gaps between merged exon + CDS intervals
        const raw = [...(isoform.cds || []), ...(isoform.exons || [])]
            .map(x => [x.start, x.end])
            .sort((a, b) => a[0] - b[0]);
        if (raw.length > 1) {
            const m = [raw[0].slice()];
            for (let i = 1; i < raw.length; i++) {
                const last = m[m.length - 1];
                if (raw[i][0] <= last[1] + 1) last[1] = Math.max(last[1], raw[i][1]);
                else m.push(raw[i].slice());
            }
            for (let i = 1; i < m.length; i++) {
                push(m[i - 1][1] + 1, m[i][0] - 1, 'intron');
            }
        }

        return out;
    }

const push = (gStart, gEnd, type) => {
            const s = flip ? (base - gEnd)   : (gStart - base);
            const e = flip ? (base - gStart) : (gEnd   - base);
            out.push({ s, e, type });
        }

function computeSegments(intervals, seqLen) {
        const bounds = new Set([0, seqLen]);
        for (const { s, e } of intervals) {
            const cs = Math.max(0, s), ce = Math.min(seqLen - 1, e);
            if (cs <= ce) { bounds.add(cs); bounds.add(ce + 1); }
        }
        const sorted = [...bounds].sort((a, b) => a - b);
        const segs = [];
        for (let i = 0; i < sorted.length - 1; i++) {
            const start = sorted[i], end = sorted[i + 1] - 1;
            const types = new Set();
            for (const { s, e, type } of intervals) {
                if (Math.max(0, s) <= start && end <= Math.min(seqLen - 1, e)) types.add(type);
            }
            segs.push({ start, end, types });
        }
        return segs;
    }

function defaultCfg(types) {
        const c = {};
        for (const t of types) {
            c[t] = {
                // Introns start HIDDEN, so the sequence opens as the spliced transcript —
                // which is what it is usually wanted for (BLAST, primers, ORFs). Hiding a
                // type cuts it from the output rather than just unstyling it, and on a
                // 15 kb gene the intronic bases otherwise bury the exonic ones. The eye
                // toggle brings them back, and the row is still listed either way.
                visible:   t !== 'intron',
                hl:        true,
                caseMode:  t === 'intron' ? 'lower' : 'upper',
                bold:      false,
                italic:    false,
                underline: false,
            };
        }
        return c;
    }

function buildControls() {
        const tbody = document.getElementById('sf-tbody');
        if (!tbody) return;
        tbody.innerHTML = '';
        for (const t of present) {
            const m = tmeta(t), s = cfg[t];
            const tr = document.createElement('tr');
            tr.innerHTML =
                `<td class="ps-2 text-center">` +
                  `<button type="button" class="btn btn-xs sf-ctrl" data-t="${t}" data-p="visible" title="${s.visible ? 'Hide — cut from sequence' : 'Show'}" style="min-width:26px;border:none;background:none;padding:2px 4px;">` +
                  `<i class="fas ${s.visible ? 'fa-eye' : 'fa-eye-slash'} ${s.visible ? 'text-secondary' : 'text-muted'}"></i></button>` +
                `</td>` +
                `<td class="ps-1">` +
                  `<span class="sf-ctrl" data-t="${t}" data-p="hl" title="${moopTh('Click to toggle highlight')}" ` +
                  `style="cursor:pointer;padding:2px 9px;border-radius:12px;font-size:0.75rem;font-weight:600;letter-spacing:0.02em;white-space:nowrap;user-select:none;${s.hl ? `background:${m.swatch};color:#fff;` : 'background:#e9ecef;color:#333;'}">${m.label}</span>` +
                `</td>` +
                `<td><select class="form-select form-select-sm sf-ctrl" data-t="${t}" data-p="case" style="min-width:80px">` +
                  `<option value="normal"${s.caseMode === 'normal' ? ' selected' : ''}>${moopTh('Original')}</option>` +
                  `<option value="upper"${s.caseMode === 'upper'   ? ' selected' : ''}>UPPER</option>` +
                  `<option value="lower"${s.caseMode === 'lower'   ? ' selected' : ''}>lower</option>` +
                `</select></td>` +
                btnTd(t, 'bold',      'B', 'font-weight:bold')      +
                btnTd(t, 'italic',    'I', 'font-style:italic')     +
                btnTd(t, 'underline', 'U', 'text-decoration:underline');
            tbody.appendChild(tr);
        }
    }

function btnTd(t, prop, label, style) {
        const active = cfg[t][prop];
        return `<td class="text-center">` +
            `<button type="button" style="${style};min-width:26px" ` +
            `class="btn btn-xs sf-ctrl sf-tog ${active ? 'btn-secondary' : 'btn-outline-secondary'}" ` +
            `data-t="${t}" data-p="${prop}">${label}</button></td>`;
    }

function wireControls() {
        const tbody = document.getElementById('sf-tbody');
        if (!tbody) return;
        tbody.addEventListener('change', onCtrl);
        tbody.addEventListener('click',  onCtrl);
    }

function onCtrl(e) {
        const el = e.target.closest('.sf-ctrl');
        if (!el) return;
        const t = el.dataset.t, p = el.dataset.p;
        if (p === 'visible' && e.type === 'click') {
            cfg[t].visible = !cfg[t].visible;
            const icon = el.querySelector('i');
            icon.className = `fas ${cfg[t].visible ? 'fa-eye text-secondary' : 'fa-eye-slash text-muted'}`;
            el.title = cfg[t].visible ? moopT('Hide — cut from sequence') : moopT('Show');
            render(); return;
        }
        if (p === 'hl' && e.type === 'click') {
            cfg[t].hl = !cfg[t].hl;
            const swatch = tmeta(t).swatch;
            el.style.background = cfg[t].hl ? swatch : '#e9ecef';
            el.style.color      = cfg[t].hl ? '#fff' : '#333';
            render(); return;
        }
        if (p === 'case' && e.type === 'change') { cfg[t].caseMode = el.value; render(); return; }
        if (['bold', 'italic', 'underline'].includes(p) && e.type === 'click') {
            cfg[t][p] = !cfg[t][p];
            el.classList.toggle('btn-secondary',         cfg[t][p]);
            el.classList.toggle('btn-outline-secondary', !cfg[t][p]);
            render();
        }
    }

function render() {
        const el = document.getElementById('sf-seq');
        if (!el || !seqStr || !segs) return;

        let html = '';
        let col  = 0;

        function emitChunk(text, style) {
            while (text.length) {
                const space = WRAP - col;
                const chunk = text.slice(0, space);
                html += style ? `<span style="${style}">${chunk}</span>` : chunk;
                col  += chunk.length;
                text  = text.slice(chunk.length);
                if (col >= WRAP) { html += '\n'; col = 0; }
            }
        }

        for (const seg of segs) {
            const hlColors = [];
            let bold = false, italic = false, underline = false, caseMode = 'normal';

            // Eye (visible): cut bases entirely if every type at this position is hidden.
            // Mixed positions (e.g. exon + CDS) stay visible as long as one type is visible.
            if (![...seg.types].some(t => cfg[t] && cfg[t].visible)) continue;

            for (const t of seg.types) {
                const s = cfg[t];
                if (!s || !s.visible) continue;          // invisible types contribute nothing
                if (s.hl) hlColors.push(tmeta(t).hl);   // chip controls highlight color
                if (s.bold)      bold      = true;
                if (s.italic)    italic    = true;
                if (s.underline) underline = true;
                if (s.caseMode === 'upper') caseMode = 'upper';
                else if (s.caseMode === 'lower' && caseMode !== 'upper') caseMode = 'lower';
            }

            const bg = blendHex(hlColors);
            let style = '';
            if (bg)        style += `background:${bg};`;
            if (bold)      style += 'font-weight:bold;';
            if (italic)    style += 'font-style:italic;';
            if (underline) style += 'text-decoration:underline;';

            let text = seqStr.slice(seg.start, seg.end + 1);
            if (caseMode === 'upper')      text = text.toUpperCase();
            else if (caseMode === 'lower') text = text.toLowerCase();

            emitChunk(text, style);
        }

        el.innerHTML = html;
    }

function emitChunk(text, style) {
            while (text.length) {
                const space = WRAP - col;
                const chunk = text.slice(0, space);
                html += style ? `<span style="${style}">${chunk}</span>` : chunk;
                col  += chunk.length;
                text  = text.slice(chunk.length);
                if (col >= WRAP) { html += '\n'; col = 0; }
            }
        }

function copyFeedback(btn, ok) {
        const orig = btn.dataset.origHtml || btn.innerHTML;
        btn.dataset.origHtml = orig;
        btn.innerHTML = ok
            ? '<i class="fas fa-check me-1"></i>' + moopTh('Copied!')
            : '<i class="fas fa-exclamation-triangle me-1"></i>' + moopTh('Copy failed — select and press Ctrl+C');
        setTimeout(() => { btn.innerHTML = orig; }, ok ? 2000 : 4000);
    }

async function writeText(text) {
        if (navigator.clipboard && window.isSecureContext) {
            try { await navigator.clipboard.writeText(text); return true; } catch { /* fall through */ }
        }
        return copyViaSelection(text, null);
    }

function copyViaSelection(text, html) {
        // Mount inside the open modal: a body-mounted node is outside the modal's focus and
        // selection scope in some engines.
        const host  = document.querySelector('.modal.show') || document.body;
        const stage = document.createElement(html ? 'div' : 'pre');
        stage.setAttribute('style', 'position:fixed;left:-9999px;top:0;font-family:monospace;white-space:pre;');
        if (html) stage.innerHTML = html; else stage.textContent = text;
        host.appendChild(stage);

        const sel = window.getSelection();
        const saved = sel.rangeCount ? sel.getRangeAt(0).cloneRange() : null;
        sel.removeAllRanges();                       // drop the user's selection, or ours loses
        const range = document.createRange();
        range.selectNodeContents(stage);
        sel.addRange(range);

        let ok = false;
        try { ok = document.execCommand('copy'); } catch { ok = false; }

        sel.removeAllRanges();
        if (saved) sel.addRange(saved);              // put the user's selection back
        stage.remove();
        return ok;
    }

async function copyRich() {
        const el  = document.getElementById('sf-seq');
        const btn = document.getElementById('sf-copy-rich');
        const inner = el.innerHTML;
        const htmlContent = `<div style="font-family:monospace;white-space:pre;">${inner}</div>`;
        let ok = false;

        if (navigator.clipboard && window.ClipboardItem && window.isSecureContext) {
            try {
                await navigator.clipboard.write([new ClipboardItem({
                    'text/html':  new Blob([htmlContent], { type: 'text/html' }),
                    'text/plain': new Blob([(el.textContent || '').trimEnd()], { type: 'text/plain' }),
                })]);
                ok = true;
            } catch { ok = false; }
        }

        if (!ok) {
            // Copy a DETACHED copy of the markup — never the live #sf-seq element.
            // selectNodeContents() on the live node copied the rendered BOX with it (its
            // background, border and padding come from CSS on the container), so pasting
            // produced a framed panel instead of a sequence.
            ok = copyViaSelection((el.textContent || '').trimEnd(), inner);
        }
        copyFeedback(btn, ok);
    }

async function copyPlain() {
        const el  = document.getElementById('sf-seq');
        const btn = document.getElementById('sf-copy-plain');
        const ok  = await writeText((el.textContent || '').trimEnd());
        copyFeedback(btn, ok);
    }

function resetControls() {
        if (!present.length) return;
        cfg = defaultCfg(present);
        buildControls();
        wireControls();
        render();
        const btn = document.getElementById('sf-reset');
        if (btn) {
            const orig = btn.dataset.origHtml || btn.innerHTML;
            btn.dataset.origHtml = orig;
            btn.innerHTML = '<i class="fas fa-check me-1"></i>Reset';
            setTimeout(() => { btn.innerHTML = orig; }, 1200);
        }
    }

function showModal() {
        ensureModal();
        bootstrap.Modal.getOrCreateInstance(document.getElementById('sf-modal')).show();
    }

function setLoading(on) {
        document.getElementById('sf-loading').style.display = on  ? '' : 'none';
        document.getElementById('sf-content').style.display = on  ? 'none' : '';
        document.getElementById('sf-error').style.display   = 'none';
    }

function showError(msg) {
        document.getElementById('sf-loading').style.display = 'none';
        document.getElementById('sf-content').style.display = 'none';
        const el = document.getElementById('sf-error');
        el.style.display = '';
        el.textContent = msg;
    }

function openFormatter(isoform) {
        activeIso = isoform;
        showModal();
        setLoading(true);

        document.getElementById('sf-isoform-label').textContent = isoform.id || '';

        const gene = geneModelData.gene;
        fetchSeq(gene.seqname, isoform.start, isoform.end, isoform.strand)
            .then(data => {
                seqStr = data.sequence || '';
                const ivals = buildIntervals(isoform);
                segs = computeSegments(ivals, seqStr.length);

                // Collect present types in preferred order
                const found = new Set();
                for (const seg of segs) { for (const t of seg.types) found.add(t); }
                present = TYPE_ORDER.filter(t => found.has(t));
                // Append any unexpected types not in the canonical order
                for (const t of found) { if (!present.includes(t)) present.push(t); }

                cfg = defaultCfg(present);

                setLoading(false);
                buildControls();
                wireControls();
                render();
            })
            .catch(err => showError(moopT('Could not fetch sequence: %s', err.message)));
    }

function init() {
        if (typeof geneModelData === 'undefined' || !geneModelData) return;
        if (typeof genomeSequenceAvailable === 'undefined' || !genomeSequenceAvailable) return;

        const btn      = document.getElementById('gene-model-fmt-btn');
        if (!btn) return;
        // A big gene's diagram shows one isoform (data-show-only); list just that one, not a
        // dropdown of every isoform -- 360 entries on the chameleon UBXN8 gene. The others
        // have their own Format button on the diagram drawn in their card.
        const svg      = document.getElementById('gene-model-svg');
        const only     = svg && svg.getAttribute('data-show-only');
        const isoforms = (geneModelData.isoforms || []).filter(i => !only || i.anchor === only);
        if (!isoforms.length) { btn.style.display = 'none'; return; }

        if (isoforms.length === 1) {
            btn.addEventListener('click', () => openFormatter(isoforms[0]));
        } else {
            // Convert plain button to a Bootstrap dropdown
            const wrap = document.createElement('div');
            wrap.className = 'dropdown';
            btn.parentNode.replaceChild(wrap, btn);
            btn.setAttribute('data-bs-toggle', 'dropdown');
            btn.classList.add('dropdown-toggle');
            wrap.appendChild(btn);

            const menu = document.createElement('ul');
            menu.className = 'dropdown-menu dropdown-menu-end';
            isoforms.forEach((iso, i) => {
                const li = document.createElement('li');
                const a  = document.createElement('a');
                a.className = 'dropdown-item small';
                a.href = '#';
                a.textContent = iso.id || `Isoform ${i + 1}`;
                a.addEventListener('click', e => { e.preventDefault(); openFormatter(iso); });
                li.appendChild(a);
                menu.appendChild(li);
            });
            wrap.appendChild(menu);
        }
    }

function resultColumnsFor(variant) {
    return RESULT_COLUMNS.filter(c => c.variants.includes('*') || c.variants.includes(variant));
}

function resultAssemblyLabel(r) {
    const acc  = r.genome_accession || '';
    const name = genomeDisplayName(r.genome_name, acc);
    if (name) return acc ? `${name} (${acc})` : name;
    return acc || '—';
}

function genomeDisplayName(name, acc) {
    const n = String(name || '').trim();
    if (!n || n === String(acc || '').trim()) return '';
    return ['na', 'n/a', 'none', 'null', '-', 'unknown'].includes(n.toLowerCase()) ? '' : n;
}

function moopStripNamingTag(text) {
    return text ? String(text).replace(MOOP_NAMING_TAG_RE, '') : text;
}

function moopRowHighlightText(r) {
    return [r.feature_name, moopStripNamingTag(r.feature_description), r.annotation_description]
        .filter(Boolean).join(' \0 ');
}

function moopFoundIn(r, keywords) {
    const trimmed = String(keywords || '').trim();
    const terms = /^".+"$/.test(trimmed) ? [trimmed.slice(1, -1)] : moopHighlightableTerms(trimmed);
    if (!terms.length || !r) return [];
    // A phrase must appear as written. The stem test trims a term's END until it matches, which is
    // right for one word (`proteins` -> `protein`) and wrong for a phrase: "forkhead box protein A2"
    // trimmed to "forkhead box protein A" claimed every FOXA1 annotation (513 of 1,075 rows, found
    // testing 2026-11-23, when 18 held the phrase).
    const found = (hay, term) => hay.indexOf(term.toLowerCase()) !== -1
        || (!/\s/.test(term) && moopTermHighlight(hay, term, false) !== null);
    const places = [
        [moopT('Name'),        [r.feature_uniquename, r.feature_name]],
        [moopT('Description'), [moopStripNamingTag(r.feature_description)]],
        [moopT('Annotation'),  [r.annotation_accession, r.annotation_description, r.annotation_source_name]],
    ].map(([label, parts]) => [label, parts.filter(Boolean).join(' \0 ').toLowerCase()]);
    // Several words: name the places holding ALL of them. When the words are split across places
    // (one in the description, one in the annotation), name each place holding any of them.
    const all = places.filter(([, hay]) => hay !== '' && terms.every(t => found(hay, t)));
    const use = all.length ? all : places.filter(([, hay]) => hay !== '' && terms.some(t => found(hay, t)));
    return use.map(([label]) => label);
}

function moopRowNoun(results) {
    const types = new Set((results || []).map(r => String(r.feature_type || '').toLowerCase()));
    const tx = ['mrna', 'transcript', 'ncrna', 'lnc_rna'];
    if (types.size && [...types].every(t => tx.includes(t))) return [moopT('transcript'), moopT('transcripts')];
    if (types.size === 1 && types.has('gene'))                 return [moopT('gene'), moopT('genes')];
    return [moopT('sequence'), moopT('sequences')];
}

function moopMatchedInNote(item, keywords) {
    const anns  = (item && item.annotations) || [];
    const trimmed = String(keywords || '').trim();
    const terms = /^".+"$/.test(trimmed) ? [trimmed.slice(1, -1)] : moopHighlightableTerms(trimmed);
    if (!terms.length || !anns.length) return '';
    const found = (hay, term) => hay.indexOf(term.toLowerCase()) !== -1 || moopTermHighlight(hay, term, false) !== null;

    const r = item.result || anns[0];
    const visible = [r.feature_uniquename, r.feature_name, moopStripNamingTag(r.feature_description)]
        .filter(Boolean).join(' \0 ').toLowerCase();
    const unseen = terms.filter(t => !found(visible, t));
    if (!unseen.length) return '';

    const hits = anns.filter(a => {
        const hay = [a.annotation_accession, a.annotation_description, a.annotation_source_name]
            .filter(Boolean).join(' \0 ').toLowerCase();
        return unseen.every(t => found(hay, t));
    });
    if (!hits.length) return '';

    const first = hits[0];
    const src   = '<span class="fw-semibold">' + escapeHtml(first.annotation_source_name || '') + '</span>';
    const what  = first.annotation_accession
        ? moopTm('matched in %1$s: %2$s', src, escapeHtml(first.annotation_accession))
        : moopTm('matched in %s', src);
    // "(+N more)" is the way in: it opens the expanded view filtered to THIS feature
    // (initializeViewToggle() handles the click), not the whole table, which would lose the row.
    const id    = escapeHtml(r.feature_uniquename || '');
    const more  = hits.length > 1
        ? ' <a href="#" class="moop-matched-more" data-feature="' + id + '" title="'
          + moopTh('Show all %1$d matches for %2$s', hits.length, r.feature_uniquename || '') + '">'
          + moopTh('(+%d more)', hits.length - 1) + '</a>'
        : '';
    // data-no-export: a hint on screen, not part of the Description a download holds
    // (datatable-config.js drops it before reading the cell).
    return '<div class="small text-muted moop-matched-in mt-1" data-no-export>' + what + more + '</div>';
}

function highlightSearchTerms(text, keywords, rowText) {
    if (!text) return text || '';
    if (!keywords) return text;
    const EXACT = `<strong style="background-color: #fff3cd; font-weight: bold;">$&</strong>`;
    const STEM  = `<strong style="background-color: #cff4fc; font-weight: bold;">$&</strong>`;

    const trimmed = keywords.trim();
    if (/^".+"$/.test(trimmed)) {
        return text.replace(new RegExp(escapeRegExp(trimmed.slice(1, -1)), 'gi'), EXACT);
    }
    // Same threshold as the search gate, and that matters: this used to require 3 while the
    // gate allowed anything 3+ overall, so a two-character term inside a longer query ran
    // but was never highlighted -- rows came back with nothing marked, reading as broken.
    const terms = moopHighlightableTerms(trimmed);
    if (terms.length === 0) return text;
    let highlighted = text;
    const haystack = rowText ? String(rowText).toLowerCase() : '';
    terms.forEach(term => {
        // Did the user's literal term appear ANYWHERE in this row? If so, cells that lack
        // it mark nothing, rather than guessing with a shortened prefix.
        const exactInRow = haystack !== '' && haystack.indexOf(term.toLowerCase()) !== -1;
        // Trim the term until it is found; null means this cell is not why the row matched.
        const hit = moopTermHighlight(highlighted, term, exactInRow);
        if (!hit) return;
        highlighted = highlighted.replace(
            new RegExp(escapeRegExp(hit.text), 'gi'),
            hit.exact ? EXACT : STEM
        );
    });
    return highlighted;
}

function resultsSelectAllId(selectId, viewType = '') {
    return 'toggle-select-btn' + selectId + (viewType ? '-' + viewType : '');
}

function buildResultsThead(variant, buttonId) {
    const FILTER_INPUT = '<input style="text-align:left; border: solid 1px #f0f0f0; border-radius: 4px; width: 100%; background-color: #ffffff; color: #212529;" type="text" placeholder="' + moopTh('Filter...') + '" class="column-search">';
    const selectAllBtn = '<button style="width:110px; height: 32px; border-radius: 4px; white-space: nowrap; border: solid 1px #808080; padding: 0; text-align: left; padding-left: 8px; display: flex; align-items: center;" class="btn btn_select_all" id="' + buttonId + '"><span>' + moopTh('Select All') + '</span></button>';

    let html = '<thead><tr>';
    resultColumnsFor(variant).forEach((col, idx) => {
        html += `<th style="width: ${col.width}px;">`
              + `<div class="column-filter-container" data-column-index="${idx}">`
              + (col.filter === false ? selectAllBtn : FILTER_INPUT)
              + `</div>`
              + `<div>${escapeHtml(col.label)}</div>`
              + `</th>`;
    });
    return html + '</tr></thead>';
}

function buildResultsTbody(variant, items, ctx) {
    const cols = resultColumnsFor(variant);
    let html = '<tbody>';
    items.forEach(item => {
        const r = item.result;
        // Both attributes are read by the FASTA export in datatable-config.js. The gene set
        // is REQUIRED, not decoration: sequences live in
        // organisms/{organism}/{assembly}/{gene_set}/, so without it the retrieval endpoint
        // fell back to a gene set named "v1" — of which zero exist anywhere in the data tree —
        // and every per-table FASTA silently returned no sequences.
        html += `<tr data-genome-accession="${encodeURIComponent(r.genome_accession || '')}"`
              + ` data-gene-set="${encodeURIComponent(r.gene_set || '')}">`;
        cols.forEach(col => { html += `<td>${col.render(r, ctx, item)}</td>`; });
        html += '</tr>';
    });
    return html + '</tbody>';
}

function resultsColumnDefs(variant) {
    // The no-export marker is read at call time so this file does not depend on
    // datatable-config.js having loaded first; the fallback keeps the literal in one
    // conceptual place if load order ever changes.
    const noExport = (typeof DataTableExportConfig !== 'undefined' && DataTableExportConfig.NO_EXPORT_CLASS)
                   || 'dt-no-export';

    return resultColumnsFor(variant).map((col, idx) => {
        const def = { targets: idx };
        if (col.orderable === false) def.orderable = false;
        // The site may change which columns show by default (Site Configuration -> Search results;
        // window.MOOP_RESULT_COLUMNS, only what differs). Select and Feature ID are never hidden.
        const siteCols = globalThis.MOOP_RESULT_COLUMNS || {};   // window in a browser; also the test sandbox
        const shown = (col.key in siteCols && col.key !== 'select' && col.key !== 'feature_id')
            ? siteCols[col.key] === true : !col.hidden;
        if (!shown)                  def.visible   = false;

        const classes = [];
        if (col.wrap)               classes.push('wrap-text');
        if (col.exportable === false) classes.push(noExport);
        if (col.cssClass)           classes.push(col.cssClass);
        if (classes.length)         def.className = classes.join(' ');

        return def;
    });
}

function resultItems(results) {
    return results.map(r => ({ result: r, annotations: null }));
}

function createOrganismResultsTable(organism, results, sitePath, linkBasePath = 'tools/parent.php', imageUrl = '', searchKeywords = '') {
    const tableId  = 'resultsTable_' + organism.replace(/[^a-zA-Z0-9]/g, '_');
    const selectId = organism.replace(/[^a-zA-Z0-9]/g, '_');
    const variant  = (results[0]?.uniquename_search ?? false) ? 'uniquename' : 'full';
    const ctx      = { sitePath, linkBasePath, organism, keywords: searchKeywords };

    const anchorId = 'results-' + selectId;
    const html = `
        <div class="organism-results" id="${anchorId}">
            <h5>${organismHeaderHtml(organism, results, sitePath, imageUrl, true)}
                <span class="badge results_annotation_count">${results.length} annotation${results.length !== 1 ? 's' : ''}</span>
            </h5>
            <div class="table-responsive" style="overflow-x: auto; width: 100%;">
                <table id="${tableId}" class="table table-sm table-striped table-hover results-table">
                    ${buildResultsThead(variant, resultsSelectAllId(selectId))}
                    ${buildResultsTbody(variant, resultItems(results), ctx)}
                </table>
            </div>
        </div>
    `;

    setTimeout(() => initializeResultsTable('#' + tableId, selectId, variant === 'uniquename'), 100);
    return html;
}

function organismHeaderHtml(organism, results, sitePath, imageUrl, linked) {
    const genus      = results[0]?.genus || '';
    const species    = results[0]?.species || '';
    const commonName = results[0]?.common_name || '';
    const fallbackId = 'icon-' + organism.replace(/[^a-zA-Z0-9]/g, '_');

    const imageHtml = imageUrl
        ? `<img src="${imageUrl}" class="organism-thumbnail" style="height: 24px; width: 24px; margin-right: 8px; border-radius: 3px;" onerror="this.style.display='none'; document.getElementById(${escapeHtml(JSON.stringify(fallbackId))}).style.display='inline';" onload="document.getElementById(${escapeHtml(JSON.stringify(fallbackId))}).style.display='none';">
           <i class="fa fa-dna" id="${fallbackId}" style="margin-right: 8px; display: none;"></i>`
        : `<i class="fa fa-dna" style="margin-right: 8px;"></i>`;

    const name = linked
        ? `<a href="${sitePath}/tools/organism.php?organism=${encodeURIComponent(organism)}" style="text-decoration: none; color: var(--moop-organism-header);"><em>${genus} ${species}</em> <i class="fa fa-external-link-alt" style="font-size: 0.8em; margin-left: 0.25rem;"></i></a>`
        : `<em>${genus} ${species}</em>`;

    return imageHtml + name + (commonName ? ` (${commonName})` : '');
}

function initializeResultsTable(tableId, selectId, isUniquenameSearch, viewType = '') {
    initResultsDataTable(tableId, isUniquenameSearch ? 'uniquename' : 'full',
                         resultsSelectAllId(selectId, viewType));
}

function initResultsDataTable(tableSelector, variant, buttonId) {
    const table = $(tableSelector).DataTable({
        dom: 'Brtlpi',
        pageLength: 25,
        stateSave: false,
        orderCellsTop: false,
        buttons: DataTableExportConfig.getSearchResultsButtons(),
        scrollX: false,
        scrollCollapse: false,
        autoWidth: false,
        fixedHeader: false,
        columnDefs: resultsColumnDefs(variant),
        colReorder: true,
        retrieve: true,
        initComplete: function () {
            // Force remove sorting classes from the Select column
            $(tableSelector + ' thead th:first-child').removeClass('sorting sorting_asc sorting_desc');
        }
    });

    // Per-column filtering. Delegated from <thead> rather than bound to each input, so a
    // column that colvis re-attaches later arrives already wired. Filtering runs against
    // DataTables' full data model, so it spans every page, not just the one on screen.
    $(tableSelector + ' thead')
        .off('keyup.moopfilter change.moopfilter')
        .on('keyup.moopfilter change.moopfilter', 'input.column-search', function () {
            const columnIndex = $(this).closest('.column-filter-container').data('column-index');
            if (columnIndex === undefined) return;
            const dt = $(tableSelector).DataTable();
            if (dt.column(columnIndex).search() !== this.value) {
                dt.column(columnIndex).search(this.value).draw();
            }
        });

    // Clicking a filter box must not sort the column underneath it.
    $(tableSelector + ' thead')
        .off('click.moopfilter')
        .on('click.moopfilter', 'input.column-search', e => e.stopPropagation());

    const syncSelectAllLabel = () => {
        const allRows = table.rows().nodes();
        const total   = $(allRows).find('input.row-select').length;
        const checked = $(allRows).find('input.row-select:checked').length;
        $('#' + buttonId).find('span').text(checked === total && total > 0 ? 'Deselect All' : 'Select All');
    };

    $('#' + buttonId).off('click').on('click', function (e) {
        e.preventDefault();
        const allRows = table.rows().nodes();
        const total   = $(allRows).find('input.row-select').length;
        const checked = $(allRows).find('input.row-select:checked').length;
        $(allRows).find('input.row-select').prop('checked', checked !== total);
        syncSelectAllLabel();
    });

    $(tableSelector).on('change', '.row-select', syncSelectAllLabel);

    return table;
}

const syncSelectAllLabel = () => {
        const allRows = table.rows().nodes();
        const total   = $(allRows).find('input.row-select').length;
        const checked = $(allRows).find('input.row-select:checked').length;
        $('#' + buttonId).find('span').text(checked === total && total > 0 ? 'Deselect All' : 'Select All');
    }

function groupResultsByFeature(results) {
    const grouped = {};
    const order = [];

    results.forEach(result => {
        const key = result.feature_uniquename;
        if (!grouped[key]) {
            grouped[key] = { feature: result, annotations: [] };
            order.push(key);
        }
        grouped[key].annotations.push(result);
    });

    return order.map(key => [key, grouped[key]]);
}

function moopRowsInSummaryOrder(results) {
    return groupResultsByFeature(results || []).flatMap(([, data]) => data.annotations);
}

