function resetPrimerForm() {
    var form = document.getElementById('primerBlastForm');
    if (!form) { return; }

    var textarea = document.getElementById('primers');
    if (textarea) {
        textarea.value = '';
    }

    clearPrimerFile();

    // Deselect the assembly, and clear the filter that may be hiding most of the list. Through
    // the selector, so its readout and row highlight follow (refresh() also calls
    // updatePrimerSelection()).
    form.querySelectorAll('input[name="selected_source"]:checked').forEach(function (radio) {
        radio.checked = false;
    });
    var filter = document.getElementById('scope-filter');
    if (filter) {
        filter.value = '';
        filter.dispatchEvent(new Event('input'));
    }
    if (primerScope) { primerScope.refresh(); } else { updatePrimerSelection(); }

    var mismatch = document.getElementById('max_mismatch');
    if (mismatch) {
        mismatch.value = form.getAttribute('data-default-mismatch') || '2';
    }

    var product = document.getElementById('max_product');
    if (product) {
        product.value = form.getAttribute('data-default-product') || '10000';
    }

    var mode = form.getAttribute('data-default-mode') || 'genome';
    var modeRadio = form.querySelector('input[name="search_mode"][value="' + mode + '"]');
    if (modeRadio) {
        modeRadio.checked = true;
    }

    // Take away the previous search's output as well. It is server-rendered HTML
    // sitting above and below the form, so clearing the INPUTS alone leaves an
    // error or a result table describing a search the form no longer represents --
    // which reads as "clearing did nothing".
    var stale = document.getElementById('primerSearchError');
    if (stale) {
        stale.remove();
    }
    var results = document.getElementById('primerResults');
    if (results) {
        results.innerHTML = '';
    }

    if (textarea) {
        textarea.focus();
    }
}

function downloadPrimerResults() {
    var node = document.getElementById('primerExportData');
    if (!node) { return; }

    var rows;
    try {
        rows = JSON.parse(node.textContent);
    } catch (e) {
        return;
    }
    if (!rows || !rows.length) { return; }

    // Header from the DATA's keys, one serialiser site-wide (moopRowsToTsv, js/modules/utilities.js),
    // byte-for-byte the same as the API's TSV (moop_rows_to_tsv). Never a column list kept here:
    // that is how a heading once silently labelled the wrong values.
    var tsv = moopRowsToTsv(rows);

    var blob = new Blob([tsv], {type: 'text/tab-separated-values'});
    var url  = URL.createObjectURL(blob);
    var a    = document.createElement('a');
    a.href = url;
    a.download = 'primer_blast_results.tsv';
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
}

function syncOptionPlaceholders() {
        if (typeof primerOptionDefaults === 'undefined') { return; }

        var checked = document.querySelector('input[name="primer_type"]:checked');
        if (!checked) { return; }

        var defaults = primerOptionDefaults[checked.value];
        if (!defaults) { return; }

        document.querySelectorAll('[data-option]').forEach(function (input) {
            var value = defaults[input.dataset.option];
            // An empty placeholder is better than a stale one: it says "primer3
            // decides" rather than naming a number from the previous preset.
            input.placeholder = (value === undefined || value === null) ? '' : String(value);
        });
    }

function syncTailFields() {
        var select = document.getElementById('tail');
        if (!select) { return; }

        var chosen = select.value;

        document.querySelectorAll('.tail-detail').forEach(function (node) {
            node.hidden = node.dataset.tail !== chosen;
        });

        var custom = document.getElementById('customTailFields');
        if (custom) {
            custom.hidden = chosen !== 'custom';
        }
    }

function downloadTsv(rows, filename) {
        if (!rows || !rows.length) { return; }

        // One serialiser site-wide (moopRowsToTsv, js/modules/utilities.js), the same rules as the API's TSV.
        var tsv = moopRowsToTsv(rows);

        var blob = new Blob([tsv], { type: 'text/tab-separated-values' });
        var url = URL.createObjectURL(blob);
        var link = document.createElement('a');

        link.href = url;
        link.download = filename;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        URL.revokeObjectURL(url);
    }

function readJson(id) {
