function updateSearchIdsDisplay() {
        if (!featureIdsTextarea) return;

        // Check if searchIdsDisplay element exists before trying to update it
        const searchIdsDisplay = document.getElementById('searchIdsDisplay');
        if (!searchIdsDisplay) {
            return; // Element doesn't exist on this page, skip
        }


        // Get user input IDs
        const rawIds = featureIdsTextarea.value.trim();
        const userInputIds = rawIds
            .split(/[\n,]+/)
            .map(id => id.trim())
            .filter(id => id.length > 0);

        // A long list is a download only (window.retrievalShowMax, the server's same limit), so
        // there is nothing to colour: say so in one line. This box used to draw every ID, on
        // every keystroke, checking each against every found ID -- slow in the browser for a
        // paste of thousands, before the server was even asked.
        const showMax = window.retrievalShowMax || 50;
        if (userInputIds.length > showMax) {
            searchIdsDisplay.textContent = moopT('%1$s IDs entered. Lists of more than %2$s IDs are available as a download only: retrieve to see how many were found.',
                                                 userInputIds.length.toLocaleString(), showMax);
            searchIdsDisplay.style.display = 'block';
            return;
        }

        // Green = found, red = not found -- but only once a retrieval has RUN. IDs pre-filled by a
        // link (a term page's "Get the sequences") have not been looked up, and painting them all
        // red read as "none of these exist" (Sofia, 2026-11-24). Until then, neutral grey.
        const retrievalRan = !!(foundIdsField && foundIdsField.dataset.ran === '1');
        const chipColor = (isFound) => !retrievalRan ? '#e9ecef' : (isFound ? '#d4edda' : '#f8d7da');

        // Found IDs: the server's list (#foundIds), taken from the FASTA headers it returned -- the one
        // source. Until 2026-11-24 an empty list fell back to window.foundIds (the same data again) and
        // then to scraping every ">token" out of the whole page's text, which could count any ">" on
        // the page as a found ID.
        let foundIds = [];
        if (retrievalRan && foundIdsField && foundIdsField.value) {
            try {
                foundIds = JSON.parse(foundIdsField.value);
            } catch (e) {
                foundIds = [];
            }
        }

        // First check if server sent expanded uniquenames (after form submission)
        let idsToDisplay = [];
        if (expandedUniqueamesField && expandedUniqueamesField.value) {
            try {
                const expanded = JSON.parse(expandedUniqueamesField.value);
                if (Array.isArray(expanded) && expanded.length > 0) {
                    idsToDisplay = expanded;
                }
            } catch (e) {
                // JSON parse failed, fall back to user input
            }
        }

        // If no expanded IDs, use user input
        if (idsToDisplay.length === 0) {
            if (!rawIds) {
                document.getElementById('searchIdsDisplay').innerHTML = 
                    '<span style="color: #999;">' + moopTh('Enter IDs above to see expanded list (including children)') + '</span>';
                searchIdsDisplay.style.display = 'block';
                return;
            }
            idsToDisplay = userInputIds;
        }

        // Display the IDs with parent-child hierarchy
        let displayHtml = '';
        const parentToChildren = window.parentToChildren || {};
        const processedIds = new Set();

        // Ensure foundIds is an array
        if (!Array.isArray(foundIds)) {
            foundIds = [];
        }

        idsToDisplay.forEach((id) => {
            if (processedIds.has(id)) return;

            const isFound = foundIds.some(foundId => foundId === id || foundId.startsWith(id + ':') || foundId.startsWith(id + ' '));
            const bgColor = chipColor(isFound);

            displayHtml += `<div style="padding: 4px 0;">
                <span style="background: ${bgColor}; padding: 2px 6px; border-radius: 3px; font-weight: bold;">${escapeHtml(id)}</span>`;

            processedIds.add(id);

            // If this ID has children, show them nested
            if (parentToChildren[id] && Array.isArray(parentToChildren[id])) {
                parentToChildren[id].forEach(childId => {
                    if (processedIds.has(childId)) return;

                    const childFound = foundIds.some(foundId => foundId === childId || foundId.startsWith(childId + ':') || foundId.startsWith(childId + ' '));
                    const childBgColor = chipColor(childFound);

                    displayHtml += `<div style="padding: 4px 0; margin-left: 20px; border-left: 2px solid #ccc; padding-left: 8px;">
                        <span style="background: ${childBgColor}; padding: 2px 6px; border-radius: 3px;">${escapeHtml(childId)}</span>
                    </div>`;

                    processedIds.add(childId);
                });
            }

            displayHtml += `</div>`;
        });

        // Add any IDs that weren't parents (in case they have no parent in display)
        idsToDisplay.forEach((id) => {
            if (processedIds.has(id)) return;

            const isFound = foundIds.some(foundId => foundId === id || foundId.startsWith(id + ':') || foundId.startsWith(id + ' '));
            const bgColor = chipColor(isFound);

            displayHtml += `<div style="padding: 4px 0;">
                <span style="background: ${bgColor}; padding: 2px 6px; border-radius: 3px;">${escapeHtml(id)}</span>
            </div>`;

            processedIds.add(id);
        });

        document.getElementById('searchIdsDisplay').innerHTML = displayHtml || 
            '<span style="color: #999;">' + moopTh('No valid IDs entered') + '</span>';
        searchIdsDisplay.style.display = 'block';
    }

function clearFeatureIds() {
    const featureIds = document.getElementById('featureIds');

    if (!featureIds) {
        console.error('featureIds field not found');
        return;
    }

    featureIds.value = '';
    featureIds.focus();
}

function refreshSampleIds(radio) {
    const p = { organism: radio.dataset.organism || '', assembly: radio.dataset.assembly || '', gene_set: radio.dataset.geneSet || '' };
    if (!p.organism || !p.assembly || !p.gene_set) return;
    const key = p.organism + '|' + p.assembly + '|' + p.gene_set;
    examplesWanted = key;
    if (examplesBySource[key]) { showExamples(examplesBySource[key]); return; }

    fetch(window.sitePath + '/api/gene_set_examples.php?' + new URLSearchParams(p), { credentials: 'same-origin' })
        .then(r => r.ok ? r.json() : { ids: [] })
        .then(ex => {
            examplesBySource[key] = ex;
            if (key === examplesWanted) showExamples(ex);   // ignore a slower, superseded answer
        })
        .catch(() => {});
}

function showExamples(ex) {
    const ids = Array.isArray(ex.ids) ? ex.ids : [];
    if (!ids.length) return;
    window.sampleFeatureIds = ids;
    const text = document.getElementById('sampleIdsText');
    if (text) text.textContent = ids.join(' · ');
    const row = document.getElementById('sampleIdsRow');
    if (row) row.style.display = '';
    if (ex.gene) document.querySelectorAll('.ex-gene').forEach(el => { el.textContent = ex.gene; });
    if (ex.transcript) document.querySelectorAll('.ex-tx').forEach(el => { el.textContent = ex.transcript; });
}

function loadSampleIds() {
    const sampleIds = typeof window.sampleFeatureIds !== 'undefined' ? window.sampleFeatureIds : [];
    const featureIds = document.getElementById('featureIds');

    if (!featureIds) {
        console.error('featureIds field not found');
        return;
    }

    if (sampleIds.length === 0) {
        console.error('No sample IDs configured');
        return;
    }

    // Load samples one per line
    featureIds.value = sampleIds.join('\n');
    featureIds.focus();
}

function choose(id, push) {
        list.hidden = true;
        viewer.show(id);
        var u = new URL(location.href);
        u.searchParams.set('gene', id);
        if (push) history.pushState({ gene: id }, '', u); else history.replaceState({ gene: id }, '', u);
    }

function esc(s) { return String(s).replace(/[&<>"']/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]; }); }
    input.addEventListener('input', function () {
        clearTimeout(timer);
        var q = input.value.trim();
        if (q.length < 2) { list.hidden = true; return; }
        timer = setTimeout(function () {
            var mine = ++seq;
            var p = new URLSearchParams({ organism: moopAtlas.organism, assembly: moopAtlas.assembly, gene_set: moopAtlas.gene_set,
                                          atlas: moopAtlas.atlas, what: 'search', q: q });
            fetch(moopAtlas.api + '?' + p).then(function (r) { return r.json(); }).then(function (d) {
                if (mine !== seq) return;
                var genes = d.genes || [];
                list.innerHTML = genes.length
                    ? genes.map(function (g) {
                        return '<button type="button" class="list-group-item list-group-item-action" role="option" data-id="' + esc(g.gene_id) + '">' +
                               (g.name ? '<strong>' + esc(g.name) + '</strong> | ' : '') + esc(g.gene_id) + '</button>';
                      }).join('')
                    : '<div class="list-group-item text-muted">' + moopTh('No matches found') + '</div>';
                list.hidden = false;
            }).catch(function () { list.hidden = true; });
        }, 200);
    });
    list.addEventListener('click', function (e) {
        var b = e.target.closest('[data-id]');
        if (b) choose(b.getAttribute('data-id'), true);
    });
    input.addEventListener('keydown', function (e) {
        if (e.key === 'Enter') {
            e.preventDefault();
            var first = list.hidden ? null : list.querySelector('[data-id]');
            if (first) choose(first.getAttribute('data-id'), true);
        } else if (e.key === 'Escape') {
            list.hidden = true;
        } else if (e.key === 'ArrowDown' && !list.hidden) {
            var f = list.querySelector('[data-id]');
            if (f) { e.preventDefault(); f.focus(); }
        }
    });
    list.addEventListener('keydown', function (e) {
        var cur = document.activeElement;
        if (e.key === 'ArrowDown' && cur.nextElementSibling) { e.preventDefault(); cur.nextElementSibling.focus(); }
        if (e.key === 'ArrowUp') { e.preventDefault(); (cur.previousElementSibling || input).focus(); }
        if (e.key === 'Escape') { list.hidden = true; input.focus(); }
    });
    document.addEventListener('click', function (e) { if (!e.target.closest('.sa-pick')) list.hidden = true; });
    input.addEventListener('focus', function () { input.select(); });
});

function el(name, attrs, parent) {
    var n = document.createElementNS(SVG, name);
    for (var k in attrs) n.setAttribute(k, attrs[k]);
    if (parent) parent.appendChild(n);
    return n;
  }

function fmtTime(t) {
    var d = new Date(t * 1000);
    var hm = pad(d.getHours()) + ':' + pad(d.getMinutes());
    if (is30d) return d.toLocaleDateString(undefined, {weekday: 'short', month: 'short', day: 'numeric'});
    return is7d ? d.toLocaleDateString(undefined, {weekday: 'short', month: 'short', day: 'numeric'}) + ' ' + hm : hm;
  }

function fmtNum(v) {
    if (v === null || v === undefined) return '—';
    if (Math.abs(v) >= 10000) return (v / 1000).toFixed(0) + 'K';
    if (Math.abs(v) >= 1000) return (v / 1000).toFixed(1) + 'K';
    return (Math.round(v * 10) / 10).toString();
  }

function niceMax(v) {
    if (!(v > 0)) return 1;
    var p = Math.pow(10, Math.floor(Math.log10(v)));
    var steps = [1, 2, 2.5, 5, 10];
    for (var i = 0; i < steps.length; i++) if (steps[i] * p >= v) return steps[i] * p;
    return 10 * p;
  }

function draw(fig) {
    var key = fig.dataset.key;
    var unit = fig.dataset.unit || '';
    var plot = fig.querySelector('.sysmon-plot');
    plot.textContent = '';
    var W = plot.clientWidth, H = plot.clientHeight;
    var svg = el('svg', {viewBox: '0 0 ' + W + ' ' + H, role: 'img'}, plot);
    var pts = series.filter(function (p) { return p[key] !== null && p[key] !== undefined; });
    if (pts.length < 2) {
      el('text', {x: W / 2, y: H / 2, 'text-anchor': 'middle', class: 'empty'}, svg).textContent = is30d
        ? 'Daily figures appear once two full days are recorded.'
        : (is7d ? 'Hourly figures appear once the first full hour is recorded.'
                : 'Not enough samples yet — the collector records one a minute.');
      return;
    }
    var t0 = series[0].t, t1 = series[series.length - 1].t;
    var dataMax = Math.max.apply(null, pts.map(function (p) { return p[key]; }));
    var yMax = fig.dataset.max ? Math.max(+fig.dataset.max, dataMax) : niceMax(dataMax);
    var iw = W - M.left - M.right, ih = H - M.top - M.bottom;
    var x = function (t) { return M.left + (t1 === t0 ? 0 : (t - t0) / (t1 - t0) * iw); };
    var y = function (v) { return M.top + ih - v / yMax * ih; };

    // Recessive grid + y ticks (0, half, top)
    [0, yMax / 2, yMax].forEach(function (v) {
      var yy = Math.round(y(v)) + 0.5;
      el('line', {x1: M.left, x2: W - M.right, y1: yy, y2: yy, class: 'grid'}, svg);
      el('text', {x: M.left - 6, y: yy + 4, 'text-anchor': 'end', class: 'tick'}, svg).textContent = fmtNum(v);
    });
    // x ticks: every 4 h (24 h view) or every midnight (7 d view)
    var tickStep = is30d ? 7 * 86400 : (is7d ? 86400 : 4 * 3600);
    var first = Math.ceil(t0 / tickStep) * tickStep;
    if (is7d || is30d) { var d0 = new Date(t0 * 1000); d0.setHours(24, 0, 0, 0); first = d0.getTime() / 1000; }
    // The start and end are always labelled (a young or short window may hold no regular tick);
    // a regular tick too close to either end is skipped so labels never collide.
    var shortTime = function (t) {
      var d = new Date(t * 1000);
      if (is30d) return d.toLocaleDateString(undefined, {month: 'short', day: 'numeric'});
      return is7d ? d.toLocaleDateString(undefined, {weekday: 'short'}) + ' ' + pad(d.getHours()) + 'h' : pad(d.getHours()) + ':' + pad(d.getMinutes());
    };
    el('text', {x: M.left, y: H - 6, 'text-anchor': 'start', class: 'tick'}, svg).textContent = shortTime(t0);
    el('text', {x: W - M.right, y: H - 6, 'text-anchor': 'end', class: 'tick'}, svg).textContent = shortTime(t1);
    for (var tt = first; tt <= t1; tt += tickStep) {
      if (x(tt) - M.left < 60 || W - M.right - x(tt) < 60) continue;
      el('text', {x: x(tt), y: H - 6, 'text-anchor': 'middle', class: 'tick'}, svg).textContent =
        is30d ? new Date(tt * 1000).toLocaleDateString(undefined, {month: 'short', day: 'numeric'})
              : (is7d ? new Date(tt * 1000).toLocaleDateString(undefined, {weekday: 'short'}) : pad(new Date(tt * 1000).getHours()) + ':00');
    }

    // Line + area, broken wherever samples are missing
    var runs = [], run = [];
    series.forEach(function (p, i) {
      var v = p[key];
      var gap = i > 0 && p.t - series[i - 1].t > 2.5 * step;
      if (v === null || v === undefined || gap) { if (run.length) runs.push(run); run = []; }
      if (v !== null && v !== undefined) run.push(p);
    });
    if (run.length) runs.push(run);
    runs.forEach(function (r) {
      var d = r.map(function (p, i) { return (i ? 'L' : 'M') + x(p.t).toFixed(1) + ',' + y(p[key]).toFixed(1); }).join('');
      if (r.length > 1) {
        el('path', {d: d + 'L' + x(r[r.length - 1].t).toFixed(1) + ',' + y(0) + 'L' + x(r[0].t).toFixed(1) + ',' + y(0) + 'Z', class: 'area'}, svg);
      }
      el('path', {d: d, class: 'line'}, svg);
      if (r.length === 1) el('circle', {cx: x(r[0].t), cy: y(r[0][key]), r: 3, class: 'dot'}, svg);
    });

    // Crosshair + tooltip (pointer and keyboard)
    var cross = el('line', {y1: M.top, y2: M.top + ih, class: 'cross', visibility: 'hidden'}, svg);
    var dot = el('circle', {r: 4.5, class: 'dot', visibility: 'hidden'}, svg);
    var tip = document.createElement('div');
    tip.className = 'sysmon-tip'; tip.hidden = true;
    var tipVal = document.createElement('strong'), tipTime = document.createElement('span');
    tip.appendChild(tipVal); tip.appendChild(tipTime);
    plot.appendChild(tip);
    var idx = pts.length - 1;

    function show(i) {
      idx = Math.max(0, Math.min(pts.length - 1, i));
      var p = pts[idx], px = x(p.t), py = y(p[key]);
      cross.setAttribute('x1', px); cross.setAttribute('x2', px); cross.setAttribute('visibility', 'visible');
      dot.setAttribute('cx', px); dot.setAttribute('cy', py); dot.setAttribute('visibility', 'visible');
      tipVal.textContent = fmtNum(p[key]) + unit;
      tipTime.textContent = fmtTime(p.t);
      tip.hidden = false;
      var left = px + 12;
      if (left + tip.offsetWidth > W) left = px - 12 - tip.offsetWidth;
      tip.style.left = left + 'px';
      tip.style.top = Math.max(0, py - tip.offsetHeight - 8) + 'px';
    }
    function hide() {
      cross.setAttribute('visibility', 'hidden'); dot.setAttribute('visibility', 'hidden'); tip.hidden = true;
    }
    function nearest(px) {
      var best = 0, bd = Infinity;
      for (var i = 0; i < pts.length; i++) {
        var dd = Math.abs(x(pts[i].t) - px);
        if (dd < bd) { bd = dd; best = i; }
      }
      return best;
    }
    var hit = el('rect', {x: M.left, y: M.top, width: iw, height: ih, fill: 'transparent'}, svg);
    hit.addEventListener('pointermove', function (e) {
      var r = svg.getBoundingClientRect();
      show(nearest((e.clientX - r.left) * W / r.width));
    });
    hit.addEventListener('pointerleave', hide);
    fig.tabIndex = 0;
    fig.onkeydown = function (e) {
      if (e.key === 'ArrowLeft') { show(idx - 1); e.preventDefault(); }
      else if (e.key === 'ArrowRight') { show(idx + 1); e.preventDefault(); }
      else if (e.key === 'Escape') hide();
    };
    fig.onfocus = function () { show(idx); };
    fig.onblur = hide;
  }

var shortTime = function (t) {
      var d = new Date(t * 1000);
      if (is30d) return d.toLocaleDateString(undefined, {month: 'short', day: 'numeric'});
      return is7d ? d.toLocaleDateString(undefined, {weekday: 'short'}) + ' ' + pad(d.getHours()) + 'h' : pad(d.getHours()) + ':' + pad(d.getMinutes());
    }

function show(i) {
      idx = Math.max(0, Math.min(pts.length - 1, i));
      var p = pts[idx], px = x(p.t), py = y(p[key]);
      cross.setAttribute('x1', px); cross.setAttribute('x2', px); cross.setAttribute('visibility', 'visible');
      dot.setAttribute('cx', px); dot.setAttribute('cy', py); dot.setAttribute('visibility', 'visible');
      tipVal.textContent = fmtNum(p[key]) + unit;
      tipTime.textContent = fmtTime(p.t);
      tip.hidden = false;
      var left = px + 12;
      if (left + tip.offsetWidth > W) left = px - 12 - tip.offsetWidth;
      tip.style.left = left + 'px';
      tip.style.top = Math.max(0, py - tip.offsetHeight - 8) + 'px';
    }

function hide() {
      cross.setAttribute('visibility', 'hidden'); dot.setAttribute('visibility', 'hidden'); tip.hidden = true;
    }

function nearest(px) {
      var best = 0, bd = Infinity;
      for (var i = 0; i < pts.length; i++) {
        var dd = Math.abs(x(pts[i].t) - px);
        if (dd < bd) { bd = dd; best = i; }
      }
      return best;
    }

function buildTable() {
    var table = document.getElementById('sysmon-series-table');
    if (!table) return;
    var cols = [['t', 'Time'], ['cpu', 'CPU %'], ['mem', 'Memory %'], ['req', 'Requests'], ['fpm', 'PHP workers busy'],
                ['iowait', 'Disk wait %'], ['dread', 'Disk reads MB/s'], ['s429', 'Refused (429)']];
    var thead = table.createTHead().insertRow();
    cols.forEach(function (c) { var th = document.createElement('th'); th.textContent = c[1]; thead.appendChild(th); });
    var tbody = table.createTBody();
    series.slice().reverse().forEach(function (p) {
      var tr = tbody.insertRow();
      cols.forEach(function (c) { tr.insertCell().textContent = c[0] === 't' ? fmtTime(p.t) : fmtNum(p[c[0]]); });
    });
  }

function say(msg) {
    status.textContent = msg;
    status.classList.remove('d-none');
  }
